CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, category VARCHAR(80) NOT NULL, price DECIMAL(10,2) NOT NULL, image_url VARCHAR(1000) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_number VARCHAR(32) NOT NULL UNIQUE, email VARCHAR(254) NOT NULL, phone VARCHAR(40) NOT NULL, full_name VARCHAR(160) NOT NULL, address_line VARCHAR(255) NOT NULL, city VARCHAR(100) NOT NULL, postal_code VARCHAR(30) NOT NULL, payment_method VARCHAR(30) NOT NULL, order_status VARCHAR(30) NOT NULL, total_amount DECIMAL(10,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(160) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, line_total DECIMAL(10,2) NOT NULL, CONSTRAINT fk_order_item_order FOREIGN KEY (order_id) REFERENCES orders(id), CONSTRAINT fk_order_item_product FOREIGN KEY (product_id) REFERENCES products(id));
CREATE INDEX idx_products_active_category ON products(active, category);
CREATE INDEX idx_orders_email ON orders(email);
